import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group } = ctx.THREE;
  const root = new Group();

  // Store timelines for cleanup
  const _timelines = [];

  // Load GLB mesh asynchronously and add to the group
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // ----- Interaction Handlers -----
  root.userData.handlers = {};

  // Hover lift (rise‑in) effect
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    root.position,
    {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }
  );
  _timelines.push(hoverTimeline);

  root.userData.handlers.hover = {
    enter: () => hoverTimeline.play(0),
    leave: () => hoverTimeline.reverse(),
  };

  // Click emit
  root.userData.handlers.click = {
    click: () => ctx.emit('hub-home.select', {}),
  };

  // ----- Cleanup -----
  root.userData.cleanup = () => {
    // Kill GSAP timelines
    _timelines.forEach((t) => t.kill());

    // Dispose of GLTF resources if they were added
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        const mat = obj.material;
        if (Array.isArray(mat)) {
          mat.forEach((m) => m.dispose());
        } else if (mat) {
          mat.dispose();
        }
      }
    });
  };

  return root;
}
